<script setup lang="ts">
import { t } from '../i18n'
import {ref} from 'vue'
import {tr} from '../i18n'
import {accountApi as api} from '../accountApi'
const emit=defineEmits(['changed'])
const current=ref(''),password=ref(''),confirmation=ref(''),otp=ref(''),busy=ref(false),error=ref(''),success=ref('')
async function save(){error.value='';success.value='';if(password.value!==confirmation.value){error.value=tr('Новые пароли не совпадают.','New passwords do not match.');return}busy.value=true;try{await api('/auth/change-password','POST',{current_password:current.value,new_password:password.value},otp.value);current.value='';password.value='';confirmation.value='';success.value=tr('Пароль изменён. Остальные сеансы завершены.','Password changed. Other sessions ended.');emit('changed')}catch(e:any){error.value=e.message}finally{busy.value=false;otp.value=''}}
</script>
<template><section class="password-security"><p class="eyebrow">{{tr('УЧЁТНЫЕ ДАННЫЕ','CREDENTIALS')}}</p><h2>{{tr('Сменить пароль','Change password')}}</h2><p class="muted">{{tr('Уникальная длинная фраза: 15–128 символов. Для администратора сначала необходимо подключить 2FA.','Use a unique passphrase of 15–128 characters. Admins must enable 2FA first.')}}</p><form @submit.prevent="save"><label>{{tr(t("Текущий пароль"),'Current password')}}<input v-model="current" type="password" autocomplete="current-password" required maxlength="1024" /></label><div class="fields"><label>{{tr(t("Новый пароль"),'New password')}}<input v-model="password" type="password" autocomplete="new-password" required minlength="15" maxlength="128" /></label><label>{{tr(t("Повторите новый пароль"),'Repeat new password')}}<input v-model="confirmation" type="password" autocomplete="new-password" required minlength="15" maxlength="128" /></label></div><label>{{tr('Код 2FA или резервный код (если 2FA включена)','2FA or recovery code (if enabled)')}}<input v-model="otp" autocomplete="one-time-code" maxlength="64" /></label><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="success" role="status" class="success">{{success}}</p><button :disabled="busy">{{busy?tr(t("Сохраняем…"),'Saving…'):tr('Сменить пароль','Change password')}}</button></form></section></template>
<style scoped>.password-security{padding:28px;border:1px solid #2b3141;border-radius:18px;color:#eef0f8;background:#151923}.eyebrow{color:#a799f8;font-size:11px;letter-spacing:.13em}h2{font-size:22px;margin:0 0 12px}.muted{color:#a5adbf;line-height:1.65}label{display:block;font-size:14px;color:#cbd0df;margin:16px 0}input{display:block;box-sizing:border-box;width:100%;padding:12px;margin-top:8px;color:white;background:#0d111b;border:1px solid #3b4358;border-radius:10px;font:inherit}input:focus{outline:2px solid #a998ef;outline-offset:2px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}button{padding:12px 16px;border:0;border-radius:10px;background:#b6a4ff;color:#111021;font:inherit;font-weight:600;cursor:pointer}button:disabled{opacity:.5}.error{color:#ffc2cf}.success{color:#8de1bf}@media(max-width:620px){.fields{grid-template-columns:1fr;gap:0}.password-security{padding:20px}}</style>
